// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(address nonOwner) internal {
        vm.assume(nonOwner != address(this));
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == false || address(c).balance == balBefore);
    }

    function testFuzz_run(address nonOwner) public {
        vm.assume(nonOwner.code.length == 0 && uint160(nonOwner) > 0xffff && nonOwner != address(this) && nonOwner != address(c) && nonOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && nonOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && nonOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && nonOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(nonOwner);
    }

    receive() external payable {}
}
